             )
    res = self._query(query)
    try:
        data = res.dictresult()[0]['data']
    except IndexError:
        raise ObjectDoesNotExistException(id)
    try:
        ndata = pg.unescape_bytea(data)
    except:

        ndata = data.replace("\\'", "'")

    ndata = ndata.replace('\\000\\001', nonTextToken)
    ndata = ndata.replace('\\012', '\n')
    return ndata

